class ArgumentParser:
    def __init__(self):
        self._arguments = {}
        self._required = set()
        self._types = {}

    def parse_arguments(self, command_string):
        args = command_string.split()[1:]
        for i in range(len(args)):
            arg = args[i]
            if self._is_long_option(arg):
                self._handle_long_option(arg)
            elif self._is_short_option(arg):
                self._handle_short_option(arg, i, args)
        missing_args = self._get_missing_required_args()
        if missing_args:
            return False, missing_args

        return True, None

    def _is_long_option(self, arg):
        return arg.startswith('--')

    def _is_short_option(self, arg):
        return arg.startswith('-')

    def _handle_long_option(self, arg):
        key_value = arg[2:].split('=')
        if len(key_value) == 2:
            self._arguments[key_value[0]] = self._convert_type(key_value[0], key_value[1])
        else:
            self._arguments[key_value[0]] = True

    def _handle_short_option(self, arg, index, args):
        key = arg[1:]
        if self._has_next_value(index, args):
            self._arguments[key] = self._convert_type(key, args[index + 1])
        else:
            self._arguments[key] = True

    def _has_next_value(self, index, args):
        return (index + 1 < len(args)) and (not args[index + 1].startswith('-'))

    def _get_missing_required_args(self):
        return self._required - set(self._arguments.keys())

    def get_argument(self, key):
        return self._arguments.get(key)

    def add_argument(self, arg, required=False, arg_type=str):
        self._add_required(arg, required)
        self._types[arg] = arg_type

    def _add_required(self, arg, required):
        if required:
            self._required.add(arg)

    def _convert_type(self, arg, value):
        try:
            return self._types[arg](value)
        except (ValueError, KeyError):
            return value

    @property
    def arguments(self):
        return dict(self._arguments)

    @arguments.setter
    def arguments(self, value):
        self._arguments = dict(value)

    @property
    def required(self):
        return frozenset(self._required)

    @required.setter
    def required(self, value):
        self._required = set(value)

    @property
    def types(self):
        return dict(self._types)

    @types.setter
    def types(self, value):
        self._types = dict(value)
